_color":"#3B3B3B","_padding":{"unit":"px","top":"5","right":"5","bottom":"5","left":"5","isLinked":true}},"elements":[],"widgetType":"text-editor"},{"id":"0a4bd53","elType":"widget","settings":{"text":" Download ","link":{"url":" #","is_external":"","nofollow":"","custom_attributes":""},"align":"center","background_color":"#B00000","_css_classes":"cuet-download-btn cuet-year-2024"},"elements":[],"widgetType":"button"}],"isInner":true},{"id":"0030072","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":50},"border_radius":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":true},"box_shadow_box_shadow_type":"yes","margin":{"unit":"px","top":"10","right":"10","bottom":"10","left":"10","isLinked":true}},"elements":[{"id":"5fcc6b2","elType":"widget","settings":{"editor":"<p>CUET -PG 2025</p>","align":"center","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"400","text_color":"#0F0F0F"},"elements":[],"widgetType":"text-editor"},{"id":"de1ecc8","elType":"widget","settings":{"editor":"<div class="d-flex gap-2 gap-sm-3 mb-3"><div class="reason_text"><div class="d-flex gap-2 gap-sm-3 mb-3"><div class="reason_text" style="text-align: center;">Download Previous Question Paper 2025</div></div></div></div>","typography_typography":"custom","typography_font_size":{"unit":"px","size":17,"sizes":[]},"text_color":"#3B3B3B","_padding":{"unit":"px","top":"5","right":"5","bottom":"5","left":"5","isLinked":true}},"elements":[],"widgetType":"text-editor"},{"id":"9449bba","elType":"widget","settings":{"text":" Download ","align":"center","background_color":"#B00000","_css_classes":"cuet-download-btn cuet-year-2025"},"elements":[],"widgetType":"button"}],"isInner":true}],"isInner":false},{"id":"5ab6530","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"1499ceb","elType":"widget","settings":{"html":"<!-- Popup Overlay -->
<div class="cuet-popup-overlay" id="cuetPopup">
    <div class="cuet-popup-box">
        <button class="cuet-popup-close" id="cuetPopupClose">&times;</button>
        <div id="cuetFormContainer">
            [contact-form-7 id="ce89ac1" title="Previous Paper Form"]
        </div>
    </div>
</div>

<style>
.cuet-popup-overlay {
    display: none;
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0,0,0,0.65);
    z-index: 99999;
    justify-content: center;
    align-items: center;
}
.cuet-popup-overlay.active {
    display: flex;
}
.cuet-popup-box {
    background: #fff;
    padding: 35px 30px;
    border-radius: 12px;
    max-width: 480px;
    width: 92%;
    position: relative;
    box-shadow: 0 10px 40px rgba(0,0,0,0.3);
}
.cuet-popup-close {
    position: absolute;
    top: 10px; right: 16px;
    font-size: 28px;
    cursor: pointer;
    color: #555;
    background: none;
    border: none;
    line-height: 1;
}
.cuet-popup-box h2 {
    font-size: 20px;
    color: #222;
    margin-bottom: 10px;
    text-align: center;
}
.cuet-popup-box .wpcf7-form input[type="text"],
.cuet-popup-box .wpcf7-form input[type="tel"],
.cuet-popup-box .wpcf7-form select {
    width: 100%;
    padding: 10px 14px;
    margin-bottom: 12px;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 14px;
    box-sizing: border-box;
    display: block;
}
.cuet-popup-box .wpcf7-form input[type="submit"] {
    background: #c0392b;
    color: #fff;
    border: none;
    padding: 12px;
    width: 100%;
    border-radius: 6px;
    font-size: 16px;
    cursor: pointer;
    font-weight: bold;
    margin-top: 5px;
}
.cuet-popup-box .wpcf7-form input[type="submit"]:hover {
    background: #a93226;
}
.popup-disclaimer {
    font-size: 11px;
    color: #888;
    margin-top: 10px;
    line-height: 1.5;
    text-align: center;
}
</style>

<script>
document.addEventListener('DOMContentLoaded', function () {

    var pdfLinks = {
        '2022': 'http://www.landmarkinstitute.com/wp-content/uploads/2026/02/CUETPG-2022-2.pdf',
        '2023': 'http://www.landmarkinstitute.com/wp-content/uploads/2026/02/CUET-PG-2023.pdf',
        '2024': 'http://www.landmarkinstitute.com/wp-content/uploads/2026/02/CUET-PG-2024-1-1.pdf',
        '2025': 'http://www.landmarkinstitute.com/wp-content/uploads/2026/02/CUET-PG-2025-3.pdf',
        'solved': 'http://www.landmarkinstitute.com/wp-content/uploads/2026/02/CUET-PG-Solved-Previous-Year-Paper-2021-2025.pdf'
    };

    var selectedYear = '';

    // Download buttons click
    document.querySelectorAll('.cuet-download-btn').forEach(function (btn) {
        btn.addEventListener('click', function (e) {
            e.preventDefault();

            this.classList.forEach(function (cls) {
                if (cls.startsWith('cuet-year-')) {
                    selectedYear = cls.replace('cuet-year-', '');
                }
            });

            var dropdown = document.querySelector('#cuetPopup select[name="target-exam"]');
            if (dropdown) dropdown.value = selectedYear;

            document.getElementById('cuetPopup').classList.add('active');
        });
    });

    // Close button
    document.getElementById('cuetPopupClose').addEventListener('click', function () {
        document.getElementById('cuetPopup').classList.remove('active');
    });

    // Outside click close
    document.getElementById('cuetPopup').addEventListener('click', function (e) {
        if (e.target === this) this.classList.remove('active');
    });

    // 🔥 FIXED DOWNLOAD LOGIC
    document.addEventListener('wpcf7mailsent', function (event) {
        var year = selectedYear;

        var inputs = event.detail.inputs;
        inputs.forEach(function (field) {
            if (field.name === 'target-exam') {
                year = field.value;
            }
        });

        // ✅ SAFE NORMALIZATION (important fix)
        if (year) {
            year = year.toString().toLowerCase().trim();
        }

        // ✅ EXTRA SAFETY for solved text mismatch
        if (year.includes('solved')) {
            year = 'solved';
        }

        console.log("Final matched year:", year);

        if (pdfLinks[year]) {
            var link = document.createElement('a');
            link.href = pdfLinks[year];
            link.setAttribute('download', 'CUET-PG-' + year + '.pdf');
            link.target = '_blank';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        } else {
            console.log("PDF not found for:", year);
        }

        setTimeout(function () {
            document.getElementById('cuetPopup').classList.remove('active');
        }, 2000);
    });

});
</script>"},"elements":[],"widgetType":"html"},{"id":"ef3876a","elType":"widget","settings":{"title":"Benefits of Solving CUET PG Previous Year Paper","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"600","title_color":"#000000"},"elements":[],"widgetType":"heading"},{"id":"423d69c","elType":"widget","settings":{"editor":"<p>Many students complete the syllabus but struggle during the examination because they are unfamiliar with the actual question pattern. Regular practice with previous year papers helps bridge this gap.</p>
